// Общие помощники автотестов trends API (#95ffe2).
// «API» = клиентский модуль сайта `api.trends.getTrends(range)` (metro-модуль, сейчас __r(807)) + view `daily_totals` (RLS).
// Вызываем модуль в живой странице под сохранённой сессией аккаунта. Часы не подменяем (context.md: сгорает refresh token).
// Одна страница на аккаунт на файл (serial): одно обновление токена за прогон, сессия сохраняется обратно в .qa/auth/<id>.json.
import { Browser, BrowserContext, Page, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

const QA = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
export const BASE_URL: string = process.env.QA_BASE_URL || QA.baseUrl;
export const SUPABASE_URL = 'https://siodtucasjpxpsfuvlfc.supabase.co';
export const AUTH_DIR = path.resolve(__dirname, '../../../auth');
export const authFile = (id: string) => path.join(AUTH_DIR, `${id}.json`);
/** Publishable (anon) key проекта — не секрет, лежит в бандле сайта; копия в .qa/auth/.sbkey. */
export const sbKey = () => fs.readFileSync(path.join(AUTH_DIR, '.sbkey'), 'utf8').trim();
const TRENDS_MODULE_ID = 807; // id metro-модуля с `api`; при пересборке сайта может смениться — тогда поиск ниже.

export type Range = Record<string, unknown>;
export type Metric = { key: string; value: number; target: number; status: string; reason: string; days: number };
export type Trends = {
  range: { kind: string; from: string; to: string; days: number };
  daysWithData: number;
  minDays: number;
  enoughData: boolean;
  notEnoughReason: string | null;
  home: { key: string; status: string }[];
  metrics: Metric[];
};
export type TrendsResult = Trends | { error: string };
export const STATUSES = ['green', 'orange', 'red'];

/** uid пользователя из сохранённой сессии (без браузера). */
export function uidFromAuthFile(id: string): string {
  const s = JSON.parse(fs.readFileSync(authFile(id), 'utf8'));
  for (const o of s.origins ?? []) for (const i of o.localStorage ?? []) {
    if (/auth-token$/.test(i.name)) return JSON.parse(i.value).user.id;
  }
  throw new Error(`В .qa/auth/${id}.json нет sb-*-auth-token`);
}

/** Открыть сайт под аккаунтом и дождаться вошедшего (не анонимного) пользователя и модуля api. */
export async function openAs(browser: Browser, id: string): Promise<{ ctx: BrowserContext; page: Page }> {
  if (!fs.existsSync(authFile(id))) throw new Error(`Нет сессии .qa/auth/${id}.json — cd .qa/e2e && ../bin/with-node22 node login-supabase.mjs ${id}`);
  const ctx = await browser.newContext({
    storageState: authFile(id),
    locale: 'he-IL',
    timezoneId: 'Asia/Jerusalem',
    viewport: { width: 1440, height: 900 },
  });
  const page = await ctx.newPage();
  await page.goto(`${BASE_URL}/home`, { waitUntil: 'domcontentloaded' });
  // Ждём действующий токен вошедшего пользователя (приложение само обновит истёкший access token).
  await page
    .waitForFunction(() => {
      const k = Object.keys(localStorage).find((n) => /^sb-.*-auth-token$/.test(n));
      if (!k) return false;
      const v = JSON.parse(localStorage.getItem(k) || 'null');
      return !!v && !!v.user && v.user.is_anonymous === false && !!v.user.email && v.expires_at * 1000 > Date.now() + 60_000;
    }, null, { timeout: 30_000 })
    .catch(() => {
      throw new Error(`ОКРУЖЕНИЕ: сессия «${id}» недействительна (аноним или истекла). Обнови: cd .qa/e2e && ../bin/with-node22 node login-supabase.mjs ${id}`);
    });
  // Модуль api: сначала известный id, при пересборке — поиск по экспортам.
  await expect
    .poll(
      () =>
        page.evaluate((modId) => {
          const w = window as any;
          if (w.__qaApi) return true;
          if (typeof w.__r !== 'function') return false;
          const pick = (m: any) => (m && m.api && m.api.trends && typeof m.api.trends.getTrends === 'function' ? m.api : null);
          let api = null;
          try { api = pick(w.__r(modId)); } catch { /* модуль ещё не загружен или id сменился */ }
          for (let i = 0; !api && i < 5000; i++) { try { api = pick(w.__r(i)); } catch { /* пропускаем */ } }
          if (api) w.__qaApi = api;
          return !!api;
        }, TRENDS_MODULE_ID),
      { message: 'на странице нет api.trends.getTrends (metro __r) — сайт пересобран иначе?', timeout: 30_000 },
    )
    .toBe(true);
  return { ctx, page };
}

/** Сохранить обновлённую сессию обратно (только если это всё ещё вошедший пользователь). */
export async function saveSession(ctx: BrowserContext, page: Page, id: string) {
  const ok = await page
    .evaluate(() => {
      const k = Object.keys(localStorage).find((n) => /^sb-.*-auth-token$/.test(n));
      const v = k ? JSON.parse(localStorage.getItem(k) || 'null') : null;
      return !!v && !!v.user && v.user.is_anonymous === false && !!v.user.email;
    })
    .catch(() => false);
  if (ok) await ctx.storageState({ path: authFile(id) });
  await ctx.close();
}

/** Вызов api.trends.getTrends(range) в странице; ошибка — { error: message }. */
export async function getTrends(page: Page, range: Range): Promise<TrendsResult> {
  return page.evaluate(async (r) => {
    try {
      const t = await (window as any).__qaApi.trends.getTrends(r);
      return {
        range: t.range,
        daysWithData: t.daysWithData,
        minDays: t.minDays,
        enoughData: t.enoughData,
        notEnoughReason: t.notEnoughReason ?? null,
        home: (t.home || []).map((m: any) => ({ key: m.key, status: m.status })),
        metrics: (t.metrics || []).map((m: any) => ({ key: m.key, value: m.value, target: m.target, status: m.status, reason: m.reason, days: m.days })),
      };
    } catch (e: any) {
      return { error: String((e && e.message) || e) };
    }
  }, range);
}

export function ok(r: TrendsResult, label: string): Trends {
  if ('error' in r) throw new Error(`${label}: getTrends вернул ошибку «${r.error}»`);
  return r;
}

/** Цель профиля (как её отдаёт приложение): kind, primary, targets, keyMetrics. */
export async function getGoal(page: Page): Promise<{ goal: any; keyMetrics: string[] }> {
  return page.evaluate(async () => {
    const d = await (window as any).__qaApi.balance.getDay();
    return { goal: d.goal ?? null, keyMetrics: d.keyMetrics ?? [] };
  });
}

/** REST Supabase из страницы с токеном вошедшего пользователя. */
export async function rest(page: Page, method: string, p: string, body?: unknown): Promise<{ status: number; body: any }> {
  return page.evaluate(
    async ({ url, key, method, body }) => {
      const k = Object.keys(localStorage).find((n) => /^sb-.*-auth-token$/.test(n))!;
      const token = JSON.parse(localStorage.getItem(k)!).access_token;
      const r = await fetch(url, {
        method,
        headers: { apikey: key, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', Prefer: 'return=representation' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      const t = await r.text();
      let b: any = t;
      try { b = JSON.parse(t); } catch { /* текст */ }
      return { status: r.status, body: b };
    },
    { url: `${SUPABASE_URL}/${p}`, key: sbKey(), method, body },
  );
}

/** uid вошедшего пользователя в странице. */
export async function pageUid(page: Page): Promise<string> {
  return page.evaluate(() => {
    const k = Object.keys(localStorage).find((n) => /^sb-.*-auth-token$/.test(n))!;
    return JSON.parse(localStorage.getItem(k)!).user.id;
  });
}

/** Сегодня по часам страницы (Asia/Jerusalem), YYYY-MM-DD — так же, как «сегодня» считает приложение. */
export async function todayIn(page: Page): Promise<string> {
  return page.evaluate(() => new Date().toLocaleDateString('sv-SE'));
}

export function addDays(iso: string, n: number): string {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

/**
 * Инварианты ответа для любого диапазона и аккаунта (AC3–AC7):
 * статус ∈ green/orange/red, у метрики значение, цель > 0 и короткая причина; home ≤ 2 и из списка метрик, первым — главная;
 * мало данных ⇔ есть причина, home пуст; нет дней с данными → нет метрик.
 */
export function expectInvariants(t: Trends, label: string) {
  expect(['no_goal', 'no_data', 'few_days', null], `${label}: notEnoughReason`).toContain(t.notEnoughReason);
  expect(t.enoughData, `${label}: enoughData ⇔ нет notEnoughReason`).toBe(t.notEnoughReason === null);
  for (const m of t.metrics) {
    expect(STATUSES, `${label}: статус ${m.key}`).toContain(m.status);
    expect(Number.isFinite(m.value), `${label}: value ${m.key} — число`).toBe(true);
    expect(m.target, `${label}: target ${m.key} > 0 (AC6 — без цели метрики нет)`).toBeGreaterThan(0);
    expect(typeof m.reason === 'string' && m.reason.trim().length > 0, `${label}: reason ${m.key} не пустой (AC5)`).toBe(true);
    expect(m.reason.length, `${label}: reason ${m.key} короткий (AC5)`).toBeLessThanOrEqual(80);
    expect(m.days, `${label}: days ${m.key} ≥ 1 (AC6 — нет метрик без данных)`).toBeGreaterThanOrEqual(1);
    expect(m.days, `${label}: days ${m.key} ≤ daysWithData`).toBeLessThanOrEqual(t.daysWithData);
  }
  expect(t.home.length, `${label}: home ≤ 2 (AC4)`).toBeLessThanOrEqual(2);
  const keys = t.metrics.map((m) => m.key);
  for (const h of t.home) expect(keys, `${label}: home ${h.key} есть в metrics`).toContain(h.key);
  if (t.home.length) expect(t.home[0].key, `${label}: home[0] = главная (первая) метрика`).toBe(keys[0]);
  if (!t.enoughData) expect(t.home, `${label}: мало данных → home пуст`).toEqual([]);
  if (t.daysWithData === 0) {
    expect(t.metrics, `${label}: нет данных → нет метрик (AC6)`).toEqual([]);
    expect(['no_data', 'no_goal'], `${label}: нет данных → причина`).toContain(t.notEnoughReason);
  }
  if (t.notEnoughReason === 'few_days') {
    expect(t.daysWithData, `${label}: few_days → есть данные`).toBeGreaterThan(0);
    expect(t.daysWithData, `${label}: few_days → дней меньше порога`).toBeLessThan(t.minDays);
  }
  if (t.enoughData) expect(t.daysWithData, `${label}: enough → дней ≥ порога`).toBeGreaterThanOrEqual(t.minDays);
}

/** Диапазоны AC1 и ожидаемые from/to/days относительно сегодняшней даты. */
export function rangeCases(today: string) {
  return [
    { name: 'day', range: { kind: 'day' }, from: today, to: today, days: 1 },
    { name: 'week', range: { kind: 'week' }, from: addDays(today, -6), to: today, days: 7 },
    { name: 'month', range: { kind: 'month' }, from: addDays(today, -29), to: today, days: 30 },
    { name: 'year', range: { kind: 'year' }, from: addDays(today, -364), to: today, days: 365 },
    { name: 'custom', range: { kind: 'custom', from: addDays(today, -10), to: addDays(today, -1) }, from: addDays(today, -10), to: addDays(today, -1), days: 10 },
    { name: 'custom-1day', range: { kind: 'custom', from: today, to: today }, from: today, to: today, days: 1 },
  ];
}

/** Неверные диапазоны AC9 и точный текст ошибки (проверено 2026-11-11 на 5 аккаунтах). */
export function badRangeCases(today: string) {
  return [
    { name: 'from > to', range: { kind: 'custom', from: addDays(today, -1), to: addDays(today, -10) }, error: 'invalid value: range' },
    { name: 'to в будущем', range: { kind: 'custom', from: addDays(today, -10), to: addDays(today, 9) }, error: 'invalid value: to' },
    { name: 'длиннее 366 дней', range: { kind: 'custom', from: addDays(today, -400), to: addDays(today, -1) }, error: 'invalid value: range' },
    { name: 'from не ISO', range: { kind: 'custom', from: '11/01/2026', to: addDays(today, -1) }, error: 'invalid value: from' },
    { name: 'неизвестный kind', range: { kind: 'quarter' }, error: 'invalid value: kind' },
    { name: 'day в будущем', range: { kind: 'day', date: addDays(today, 1) }, error: 'invalid value: date' },
    { name: 'несуществующая дата 2026-04-31', range: { kind: 'custom', from: '2026-04-31', to: '2026-05-02' }, error: 'invalid value: from' },
    { name: 'custom без to', range: { kind: 'custom', from: addDays(today, -10) }, error: 'invalid value: to' },
  ];
}
